-- Pricing (R3 3B): hand-written SQL for TaxRate, ProductTax and the tax columns of Product.
-- Prisma generates the tables; this adds what it cannot express. For a database that already has the
-- baseline, paste this file at the end of the migration generated by `npx prisma migrate dev --create-only
-- --name taxes` (after Prisma's own statements). The baseline script (npm run db:baseline) appends every file
-- in prisma/sql/ after prisma/audit.sql, in name order.

-- Audit columns on every row. Tax changes are logged; the join rows are only stamped (the product's own row
-- logs the price that results).
SELECT audit_attach('TaxRate');
SELECT audit_attach('ProductTax', '', '', false);

-- Changing priceTtc alone (a tax rate changed, so many products are recomputed) writes no log row; the price
-- itself still does. For an existing database this re-attaches the trigger with that exception.
SELECT audit_attach('Product', 'priceTtc');

-- A percentage is above 0 and at most 100; a fixed amount is above 0 and has at most 3 decimals (millimes).
ALTER TABLE "TaxRate" ADD CONSTRAINT "TaxRate_value_positive" CHECK ("value" > 0);
ALTER TABLE "TaxRate" ADD CONSTRAINT "TaxRate_percentage_max" CHECK ("kind" <> 'PERCENTAGE' OR "value" <= 100);
ALTER TABLE "TaxRate" ADD CONSTRAINT "TaxRate_fixed_millimes" CHECK ("kind" <> 'FIXED' OR "value" = round("value", 3));

-- The price a buyer pays is never below zero.
ALTER TABLE "Product" ADD CONSTRAINT "Product_priceTtc_not_negative" CHECK ("priceTtc" >= 0);

-- Products from before taxes existed have no taxes, so their price with tax is their price. Safe to run again.
UPDATE "Product" SET "priceTtc" = "price" WHERE "priceTtc" = 0 AND "price" > 0;
